hooks.command:
python3 -c 'import json, subprocess, sys
output = {}
try:
    child = subprocess.run([sys.executable, sys.argv[1]], input=sys.stdin.read(1048576), text=True, capture_output=True, timeout=2)
    parsed = json.loads(child.stdout) if child.returncode == 0 else {}
    specific = parsed.get("hookSpecificOutput", {}) if isinstance(parsed, dict) else {}
    if isinstance(specific, dict) and specific.get("hookEventName") == "UserPromptSubmit" and isinstance(specific.get("additionalContext"), str):
        output = {"hookSpecificOutput": {"hookEventName": "UserPromptSubmit", "additionalContext": specific["additionalContext"]}}
except Exception:
    pass
print(json.dumps(output))' "${PLUGIN_ROOT}/scripts/title_hook.py" 2>/dev/null || printf '{}\n'
